type JobStatus = "completed" | "processing" | "queued" | "failed";

interface JobCardProps {
  fileName: string;
  status: JobStatus;
  progress: number;
  phiRemoved: number;
  duration?: string;
  onDownload?: () => void;
  onDetails?: () => void;
}

function JobCard({
  fileName,
  status,
  progress,
  phiRemoved,
  duration,
  onDownload,
  onDetails,
}: JobCardProps) {
  const statusConfig = {
    completed: {
      label: "Completed",
      color: "text-green-400",
      bg: "bg-green-500/10",
      border: "border-green-500/20",
      icon: "✔",
    },
    processing: {
      label: "Processing",
      color: "text-blue-400",
      bg: "bg-blue-500/10",
      border: "border-blue-500/20",
      icon: "⟳",
    },
    queued: {
      label: "Queued",
      color: "text-gray-400",
      bg: "bg-gray-500/10",
      border: "border-gray-500/20",
      icon: "⏳",
    },
    failed: {
      label: "Failed",
      color: "text-red-400",
      bg: "bg-red-500/10",
      border: "border-red-500/20",
      icon: "✖",
    },
  };

  const config = statusConfig[status];

  return (
    <div className={`bg-slate-900 border ${config.border} rounded-2xl p-5 shadow-sm hover:shadow-md transition`}>
      
      {/* Header */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-3">
          <div className={`w-10 h-10 flex items-center justify-center rounded-xl ${config.bg} ${config.color} text-lg`}>
            {config.icon}
          </div>

          <div>
            <p className="text-white font-semibold">{fileName}</p>
            <p className="text-sm text-gray-400">
              PHI removed: {phiRemoved} {duration && `• ${duration}`}
            </p>
          </div>
        </div>

        {/* Status Badge */}
        <span className={`px-3 py-1 rounded-full text-xs font-medium ${config.bg} ${config.color}`}>
          {config.label}
        </span>
      </div>

      {/* Progress Bar */}
      <div className="w-full bg-slate-800 rounded-full h-2 overflow-hidden mb-2">
        <div
          className="h-2 bg-blue-500 transition-all duration-500"
          style={{ width: `${progress}%` }}
        />
      </div>

      <div className="flex justify-between text-xs text-gray-400 mb-4">
        <span>{progress}%</span>
        {status === "processing" && <span>Processing...</span>}
      </div>

      {/* Actions */}
      <div className="flex gap-2">
        {status === "completed" && (
          <button
            onClick={onDownload}
            className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg transition"
          >
            Download
          </button>
        )}

        <button
          onClick={onDetails}
          className="px-3 py-1.5 bg-slate-800 hover:bg-slate-700 text-gray-300 text-sm rounded-lg transition"
        >
          Details
        </button>

        {status === "failed" && (
          <button className="px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white text-sm rounded-lg transition">
            Retry
          </button>
        )}
      </div>
    </div>
  );
}

export default function ProcessingPage() {
  return (
    <div className="p-6 space-y-4 bg-slate-950 min-h-screen">
      <JobCard
        fileName="CT_Chest_Series.dcm"
        status="completed"
        progress={100}
        phiRemoved={47}
        duration="12s"
      />

      <JobCard
        fileName="Discharge_Summary.pdf"
        status="processing"
        progress={60}
        phiRemoved={12}
      />

      <JobCard
        fileName="Lab_Results.csv"
        status="queued"
        progress={0}
        phiRemoved={0}
      />
    </div>
  );
}